async function loadFinanceSummary(){const target=document.querySelector('[data-finance-summary]');if(!target)return;target.textContent='Загружаем баланс…';try{const r=await fetch('/api/finance/balance',{cache:'no-store'});if(!r.ok)throw Error();const data=await r.json(),s=data.student;const rub=n=>(n/100).toLocaleString('ru-RU',{minimumFractionDigits:2,maximumFractionDigits:2})+' ₽';target.textContent='Баланс: '+rub(s.balance_kopecks)+'. '+(s.debt_kopecks>0?'Задолженность: '+rub(s.debt_kopecks)+'.':s.available_lessons===null?'Количество доступных уроков можно оценить после указания цены.':'Хватит на '+s.available_lessons+' полных уроков по текущей цене '+rub(s.current_price_kopecks)+'. Остаток: '+rub(s.remainder_kopecks)+'.');}catch{target.textContent='Баланс временно недоступен. Откройте раздел оплат и попробуйте обновить.'}}
